-- World fixes: Darkshore, Shatterspear Vale before and after The Ancients' Ire (2026-11-18)
-- Four: the village should be the aftermath of the battle, like 8.3.7 (TDB 8.3.7 has every Shatterspear
-- Champion and Raider lying dead). Two live quests need the trolls alive: The Ancients' Ire (13514,
-- Kerlonian Evershade: kill 30 Shatterspear Champions, burn 6 huts) and Shatterspear Laborers (13504,
-- the Laborers at the war camp, not touched here). So the village is phased (our own phasing, not 8.3.7):
--   phase 308: the living Shatterspear Champions, seen in Darkshore until 13514 is turned in
--   phase 310: 41 dead Shatterspear Champions at the 8.3.7 spots, seen in Darkshore after 13514 is turned in
-- Phases 308 and 310 exist in Phase.db2 (normal, flags 0) and are used nowhere else here.
-- Safe to run twice.

-- 1. The 18 classic Shatterspear Trolls 10919 and 3 Shatterspear Drummers 11196 standing in the village
--    are not in 8.3.7
DELETE FROM `creature_addon` WHERE `guid` IN (99735,99734,66048,66047,66024,65975,65974,65973,65972,65966,65906,65889,65885,65723,65719,65646,66023,66055,66054,66051,65907);
DELETE FROM `creature` WHERE `guid` IN (99735,99734,66048,66047,66024,65975,65974,65973,65972,65966,65906,65889,65885,65723,65719,65646,66023,66055,66054,66051,65907);

-- 2. Shatterspear Raider 33071 (immune to everyone, no quest uses it) lies dead for everyone, as in 8.3.7
UPDATE `creature_template` SET `unit_flags`=537166592,`unit_flags2`=2049,`unit_flags3`=8192 WHERE `entry`=33071;
UPDATE `creature` SET `MovementType`=0,`spawndist`=0 WHERE `id`=33071 AND `map`=1;
UPDATE `creature_addon` SET `emote`=0 WHERE `guid` IN (SELECT `guid` FROM (SELECT `guid` FROM `creature` WHERE `id`=33071 AND `map`=1) t);

-- 3. Living Shatterspear Champions move to phase 308 and stand still (8.3.7 has no wandering trolls);
--    the 7 already lying dead (aura 29266) stay in every phase
UPDATE `creature` SET `PhaseId`=308,`MovementType`=0,`spawndist`=0 WHERE `guid` IN (247325,247326,247328,247330,247331,247333,247334,247335,247336,247341,247344,247347,247348,247349,247453,247582,247583,247585,247586,247644,247645,247683,247693,247712,247720,247728,247739,247748,247750);
UPDATE `creature` SET `MovementType`=0,`spawndist`=0 WHERE `guid` IN (245622,245627,245629,245740,245742,245788,245790);

-- 4. Shatterspear Priestesses (alive in 8.3.7 too) and the hut fire bunnies stand still, as in 8.3.7
UPDATE `creature` SET `MovementType`=0,`spawndist`=0 WHERE `id` IN (32855,33913) AND `map`=1 AND `MovementType`=1;

-- 5. The 8.3.7 dead Champions (spawn flags: dead, stunned, immune), phase 310
DELETE FROM `creature` WHERE `guid` BETWEEN 735401069 AND 735401109;

-- 6. Phases for all of Darkshore (zone 148)
DELETE FROM `phase_area` WHERE `AreaId`=148 AND `PhaseId` IN (308,310);
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=26 AND `SourceGroup` IN (308,310) AND `SourceEntry`=148;
